-- gigs_near: gigs within 25 km of Manchester in the next 30 days (CatalogReadRepository.gigs).
-- Source: the statement's text as pg_stat_statements and auto_explain record it, with the binds auto_explain logged
-- ("Query Parameters") for one request as perf_u6 (01904b8f-23fc-7e81-99a6-eb4644d73a85) on the small profile (seed 42, loaded
-- by seed-scale at 2025-10-02 18:55Z), captured 2025-10-02T19:16Z from the perf API built at 0acebf9. The ids exist only in
-- that load: after another seed-scale, recapture them.
-- check: select count(*) > 0 from catalog.gig
prepare q as
select "catalog"."gig"."id", "catalog"."gig"."title", "catalog"."gig"."starts_at", "catalog"."gig"."status", "catalog"."gig"."image_url", "catalog"."gig"."ticket_url", "catalog"."gig"."price_min", "catalog"."gig"."price_max", "catalog"."gig"."currency", "catalog"."venue"."id", "catalog"."venue"."name", "catalog"."venue"."city", ST_Y("catalog"."venue"."location"::geometry), ST_X("catalog"."venue"."location"::geometry), "catalog"."venue"."coverage_note", round((ST_Distance("catalog"."gig"."location", ST_SetSRID(ST_MakePoint(cast($1 as double precision), cast($2 as double precision)), 4326)::geography) / 1000.0)::numeric, 1)::float8, "catalog"."gig"."created_by" from "catalog"."gig" join "catalog"."venue" on "catalog"."venue"."id" = "catalog"."gig"."venue_id" where ((ST_DWithin("catalog"."gig"."location", ST_SetSRID(ST_MakePoint(cast($3 as double precision), cast($4 as double precision)), 4326)::geography, cast($5 as double precision))) and "catalog"."gig"."starts_at" >= cast($6 as timestamp(6) with time zone) and "catalog"."gig"."starts_at" < cast($7 as timestamp(6) with time zone) and "catalog"."gig"."status" <> $8) order by "catalog"."gig"."starts_at" asc, "catalog"."gig"."id" asc fetch next $9 rows only;
explain (analyze, buffers, format text) execute q('-2.2426', '53.4808', '-2.2426', '53.4808', '25000', '2026-10-06 01:08:55+00:00', '2026-11-05 01:08:55+00:00', 'UNLISTED', '21');
